      providers: [
        provideRouter([{ path: '', component: PulsePageComponent }]),
        provideHttpClient(),
        provideHttpClientTesting(),
      ],
    });
  });

  afterEach(() => TestBed.inject(HttpTestingController).verify());

  it('rebuilds every filter from the URL alone, as a reload would', async () => {
    const harness = await RouterTestingHarness.create(
      '/?accountId=6&baselineWeeks=12&eventType=call_received&weekStart=2026-07-20',
    );
    const component = harness.routeDebugElement!.componentInstance as PulsePageComponent;

    expect(component.filters()).toEqual({
      accountId: 6,
      baselineWeeks: 12,
      eventType: 'call_received',
      weekStart: '2026-07-20',
    });
  });

  it('requests exactly what the URL asked for, with nothing held in memory', async () => {
    const harness = await RouterTestingHarness.create(
      '/?accountId=6&baselineWeeks=12&eventType=call_received&weekStart=2026-07-20',
    );
    const http = TestBed.inject(HttpTestingController);

    http.expectOne(() => true).flush([]);   // GET /api/accounts

    const request = http.expectOne(
      (r) => r.url === '/api/accounts/6/weekly-pulse',
    );
    expect(request.request.params.get('baselineWeeks')).toBe('12');
    expect(request.request.params.get('eventType')).toBe('call_received');
    expect(request.request.params.get('weekStart')).toBe('2026-07-20');
    request.flush(emptyPulse);

    harness.detectChanges();
  });

  it('writes a changed filter back into the URL so the next reload keeps it', async () => {
    const harness = await RouterTestingHarness.create('/?accountId=6');
    const component = harness.routeDebugElement!.componentInstance as PulsePageComponent;
    const http = TestBed.inject(HttpTestingController);

    http.match(() => true).forEach((r) => r.flush(r.request.url.endsWith('accounts') ? [] : emptyPulse));

    component.patch({ baselineWeeks: 12 });
    await harness.fixture.whenStable();

    expect(TestBed.inject(Router).url).toContain('baselineWeeks=12');
    expect(TestBed.inject(Router).url).toContain('accountId=6');   // merged, not replaced

    http.match(() => true).forEach((r) => r.flush(emptyPulse));
  });
});

/**
 * A URL is user-editable and can be stale — a bookmark saved before an option was removed,
 * or a hand-typed value. Falling back beats rendering an impossible state.
 */
describe('readFilters', () => {
  it('keeps valid values', () => {
    expect(readFilters(convertToParamMap({
      accountId: '6', baselineWeeks: '12', eventType: 'lead_created', weekStart: '2026-07-20',
    }))).toEqual({
      accountId: 6, baselineWeeks: 12, eventType: 'lead_created', weekStart: '2026-07-20',
    });
  });

  it('falls back when the URL is empty', () => {
    expect(readFilters(convertToParamMap({})))
      .toEqual({ accountId: 1, baselineWeeks: 8, eventType: 'all', weekStart: null });
  });

  it('rejects a baseline window the API would refuse', () => {
    expect(readFilters(convertToParamMap({ baselineWeeks: '7' })).baselineWeeks).toBe(8);
  });

  it('rejects an unknown event type', () => {
    expect(readFilters(convertToParamMap({ eventType: 'smoke_signal' })).eventType).toBe('all');
  });

  it('rejects a malformed week', () => {
    expect(readFilters(convertToParamMap({ weekStart: 'last-monday' })).weekStart).toBeNull();
  });
});

